('item', 'Pistola sinalizadora', '{"categoria": "0", "espacos": 1, "subtipo": "Operacional"}'::jsonb, 'Sinalizador luminoso; como arma de disparo leve causa 2d6 de fogo em alcance curto. 2 cargas.', 'Livro de Regras, p. 66'),
('item', 'Soqueira', '{"categoria": "0", "espacos": 1, "subtipo": "Operacional"}'::jsonb, '+1 no dano desarmado; aceita modificações e maldições de armas corpo a corpo.', 'Livro de Regras, p. 66'),
('item', 'Spray de pimenta', '{"categoria": "I", "espacos": 1, "subtipo": "Operacional"}'::jsonb, 'Ação padrão, alvo adjacente fica cego por 1d4 rodadas (Fortitude evita). Dois usos.', 'Livro de Regras, p. 66'),
('item', 'Taser', '{"categoria": "I", "espacos": 1, "subtipo": "Operacional"}'::jsonb, 'Ação padrão, alvo adjacente sofre 1d6 de eletricidade e fica atordoado 1 rodada (Fortitude evita). Dois usos.', 'Livro de Regras, p. 66'),
('item', 'Traje hazmat', '{"categoria": "I", "espacos": 2, "subtipo": "Operacional"}'::jsonb, '+5 contra efeitos ambientais e resistência a químico 10.', 'Livro de Regras, p. 66'),
('item', 'Amarras de (elemento)', '{"categoria": "II", "espacos": 1, "subtipo": "Paranormal"}'::jsonb, 'Contra criaturas vulneráveis ao elemento: armadilha de 3x3m que imobiliza (2 PE) ou laço que paralisa em alcance curto (1 PE, +1 PE por rodada).', 'Livro de Regras, p. 66'),
('item', 'Câmera de aura paranormal', '{"categoria": "II", "espacos": 1, "subtipo": "Paranormal"}'::jsonb, 'Ação padrão e 1 PE por foto: revela auras paranormais, na cor do elemento.', 'Livro de Regras, p. 66'),
('item', 'Componentes ritualísticos de (elemento)', '{"categoria": "0", "espacos": 1, "subtipo": "Paranormal"}'::jsonb, 'Necessários para conjurar rituais daquele elemento (não existem de Medo).', 'Livro de Regras, p. 66'),
('item', 'Emissor de pulsos paranormais', '{"categoria": "II", "espacos": 1, "subtipo": "Paranormal"}'::jsonb, 'Ação completa e 1 PE: atrai criaturas de um elemento e afasta as do elemento oposto (Vontade evita).', 'Livro de Regras, p. 67'),
('item', 'Escuta de ruídos paranormais', '{"categoria": "II", "espacos": 1, "subtipo": "Paranormal"}'::jsonb, '2 PE para gravar por 24h; ouvir a gravação dá +5 em Ocultismo para identificar criaturas.', 'Livro de Regras, p. 67'),
('item', 'Medidor de estabilidade da Membrana', '{"subtipo": "Paranormal"}'::jsonb, 'Com Ocultismo, avalia o estado da Membrana numa área e o risco de manifestação.', 'Livro de Regras, p. 67'),
('item', 'Scanner de manifestação paranormal de (elemento)', '{"categoria": "II", "espacos": 1, "subtipo": "Paranormal"}'::jsonb, 'Ação padrão e 1 PE por rodada: indica a direção de manifestações do elemento em alcance longo.', 'Livro de Regras, p. 67'),
('poder_paranormal', 'Aprender Ritual', '{"elemento": "Varia"}'::jsonb, 'Aprende um ritual de 1º círculo (2º a partir de NEX 45%, 3º a partir de 75%) e pode trocar um ritual conhecido. Pode ser escolhido várias vezes; conta como poder do elemento do ritual.', 'Livro de Regras, p. 114'),
('poder_paranormal', 'Resistir a (Elemento)', '{"elemento": "Varia", "afinidade": "Resistência sobe para 20."}'::jsonb, 'Resistência 10 contra Conhecimento, Energia, Morte ou Sangue (à escolha).', 'Livro de Regras, p. 114'),
('poder_paranormal', 'Expansão de Conhecimento', '{"elemento": "Conhecimento", "afinidade": "Aprende um segundo poder de outra classe.", "prerequisitos": "Conhecimento 1"}'::jsonb, 'Aprende um poder de outra classe (cumprindo os pré-requisitos dele).', 'Livro de Regras, p. 115'),
('poder_paranormal', 'Percepção Paranormal', '{"elemento": "Conhecimento", "afinidade": "Pode rolar de novo até dois dados."}'::jsonb, 'Ao procurar pistas, pode rolar de novo um dado abaixo de 10 (fica com o novo resultado).', 'Livro de Regras, p. 115'),
('poder_paranormal', 'Precognição', '{"elemento": "Conhecimento", "afinidade": "Imune a desprevenido.", "prerequisitos": "Conhecimento 1"}'::jsonb, '+2 em Defesa e nos testes de resistência.', 'Livro de Regras, p. 115'),
('poder_paranormal', 'Sensitivo', '{"elemento": "Conhecimento", "afinidade": "Em testes opostos com essas perícias, o oponente sofre –1 dado."}'::jsonb, '+5 em Diplomacia, Intimidação e Intuição.', 'Livro de Regras, p. 115'),
('poder_paranormal', 'Visão do Oculto', '{"elemento": "Conhecimento", "afinidade": "Ignora camuflagem."}'::jsonb, '+5 em Percepção e visão no escuro.', 'Livro de Regras, p. 115'),
('poder_paranormal', 'Afortunado', '{"elemento": "Energia", "afinidade": "Também uma vez por teste, rola de novo um 1 no d20."}'::jsonb, 'Uma vez por rolagem, rola de novo um 1 em dado que não seja d20.', 'Livro de Regras, p. 115'),
('poder_paranormal', 'Campo Protetor', '{"elemento": "Energia", "afinidade": "Também +5 em Reflexos; passar num Reflexos de meio dano anula o dano todo até seu próximo turno.", "prerequisitos": "Energia 1"}'::jsonb, 'Ao se esquivar, pode gastar 1 PE para ganhar +5 em Defesa.', 'Livro de Regras, p. 115'),
('poder_paranormal', 'Causalidade Fortuita', '{"elemento": "Energia", "afinidade": "A redução de 5 vale sempre."}'::jsonb, 'Na investigação, a DT para achar pistas cai 5 até você encontrar uma.', 'Livro de Regras, p. 115'),
('poder_paranormal', 'Golpe de Sorte', '{"elemento": "Energia", "afinidade": "+1 no multiplicador de crítico.", "prerequisitos": "Energia 1"}'::jsonb, '+1 na margem de ameaça dos seus ataques.', 'Livro de Regras, p. 115'),
('poder_paranormal', 'Manipular Entropia', '{"elemento": "Energia", "afinidade": "O alvo rola de novo todos os dados que você escolher.", "prerequisitos": "Energia 1"}'::jsonb, '2 PE: um alvo em alcance curto (não você) rola de novo um dado de um teste de perícia.', 'Livro de Regras, p. 115'),
('poder_paranormal', 'Encarar a Morte', '{"elemento": "Morte", "afinidade": "O aumento vira +3 no total."}'::jsonb, 'Em cenas de ação, limite de gasto de PE +1 (não muda a DT).', 'Livro de Regras, p. 115'),
('poder_paranormal', 'Escapar da Morte', '{"elemento": "Morte", "afinidade": "Evita o dano por completo; com dano massivo fica com 1 PV.", "prerequisitos": "Morte 1"}'::jsonb, 'Uma vez por cena, dano que o levaria a 0 PV o deixa com 1 PV (exceto dano massivo).', 'Livro de Regras, p. 115'),
('poder_paranormal', 'Potencial Aprimorado', '{"elemento": "Morte", "afinidade": "+2 PE por NEX no total."}'::jsonb, '+1 PE por NEX, acompanhando os próximos aumentos.', 'Livro de Regras, p. 115'),
('poder_paranormal', 'Potencial Reaproveitado', '{"elemento": "Morte", "afinidade": "Ganha 3 PE temporários."}'::jsonb, 'Uma vez por rodada, ao passar num teste de resistência, ganha 2 PE temporários (somem no fim da cena).', 'Livro de Regras, p. 115'),
('poder_paranormal', 'Surto Temporal', '{"elemento": "Morte", "afinidade": "Pode usar uma vez por turno.", "prerequisitos": "Morte 2"}'::jsonb, 'Uma vez por cena, no seu turno, 3 PE para uma ação padrão extra.', 'Livro de Regras, p. 115'),
('poder_paranormal', 'Anatomia Insana', '{"elemento": "Sangue", "afinidade": "Imune a críticos e ataques furtivos.", "prerequisitos": "Sangue 2"}'::jsonb, '50% de chance (par em 1d4) de ignorar o dano extra de crítico ou ataque furtivo.', 'Livro de Regras, p. 116'),
('poder_paranormal', 'Arma de Sangue', '{"elemento": "Sangue", "afinidade": "A arma fica permanente e causa 1d10."}'::jsonb, 'Movimento e 2 PE: cria uma arma natural (1d6 de Sangue) até o fim da cena; ao agredir, 1 PE por um ataque extra com ela.', 'Livro de Regras, p. 116'),
('poder_paranormal', 'Sangue de Ferro', '{"elemento": "Sangue", "afinidade": "+5 em Fortitude e imunidade a venenos e doenças."}'::jsonb, '+2 PV por NEX, acompanhando os próximos aumentos.', 'Livro de Regras, p. 116'),
('poder_paranormal', 'Sangue Fervente', '{"elemento": "Sangue", "afinidade": "O bônus sobe para +2.", "prerequisitos": "Sangue 2"}'::jsonb, 'Enquanto machucado, +1 em Agilidade ou Força (escolhe a cada vez).', 'Livro de Regras, p. 116'),
('poder_paranormal', 'Sangue Vivo', '{"elemento": "Sangue", "afinidade": "Cura acelerada 5.", "prerequisitos": "Sangue 1"}'::jsonb, 'Na primeira vez machucado na cena, ganha cura acelerada 2 (até metade dos PV máximos).', 'Livro de Regras, p. 116'),
('ritual', 'Alterar Destino', '{"elemento": "Energia", "circulo": 4, "custo_pe": 10, "execucao": "reação", "alcance": "pessoal", "alvo": "você", "duracao": "instantânea", "verdadeiro": "+5 PE: pode beneficiar um aliado em alcance curto."}'::jsonb, '+15 em um teste de resistência ou na Defesa contra um ataque.', 'Livro de Regras, p. 124'),
('ritual', 'Alterar Memória', '{"elemento": "Conhecimento", "circulo": 3, "custo_pe": 6, "execucao": "padrão", "alcance": "toque", "alvo": "1 pessoa", "duracao": "instantânea", "resistencia": "Vontade anula", "verdadeiro": "+4 PE: memórias de até 24 horas (4º círculo)."}'::jsonb, 'Altera ou apaga memórias da última hora do alvo; ele as recupera em 1d4 dias.', 'Livro de Regras, p. 124'),
('ritual', 'Amaldiçoar Arma', '{"elemento": "Varia", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "toque", "alvo": "1 arma corpo a corpo ou pacote de munição", "duracao": "cena", "discente": "+2 PE: +2d6 (2º círculo).", "verdadeiro": "+5 PE: +4d6 (3º círculo e afinidade)."}'::jsonb, 'Elemento escolhido ao aprender (Conhecimento, Energia, Morte ou Sangue). A arma causa +1d6 de dano desse elemento.', 'Livro de Regras, p. 124'),
('ritual', 'Amaldiçoar Tecnologia', '{"elemento": "Energia", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "toque", "alvo": "1 acessório ou arma de fogo", "duracao": "cena", "discente": "+2 PE: duas modificações (2º círculo).", "verdadeiro": "+5 PE: três modificações (3º círculo e afinidade)."}'::jsonb, 'O item recebe uma modificação à sua escolha.', 'Livro de Regras, p. 124'),
('ritual', 'Âncora Temporal', '{"elemento": "Morte", "circulo": 3, "custo_pe": 6, "execucao": "padrão", "alcance": "curto", "alvo": "1 ser", "duracao": "cena", "resistencia": "Vontade parcial", "verdadeiro": "+4 PE: seres escolhidos (4º círculo)."}'::jsonb, 'No início de cada turno, se falhar em Vontade, o alvo não pode se deslocar. Dois sucessos seguidos encerram.', 'Livro de Regras, p. 124'),
('ritual', 'Aprimorar Físico', '{"elemento": "Sangue", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "toque", "alvo": "1 ser", "duracao": "cena", "discente": "+3 PE: +2 (3º círculo).", "verdadeiro": "+7 PE: +3 (4º círculo e afinidade)."}'::jsonb, '+1 em Agilidade ou Força, à escolha do alvo.', 'Livro de Regras, p. 125'),
('ritual', 'Aprimorar Mente', '{"elemento": "Conhecimento", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "toque", "alvo": "1 ser", "duracao": "cena", "discente": "+3 PE: +2 (3º círculo).", "verdadeiro": "+7 PE: +3 (4º círculo e afinidade)."}'::jsonb, '+1 em Intelecto ou Presença, à escolha do alvo (não dá PE nem perícias).', 'Livro de Regras, p. 125'),
('ritual', 'Armadura de Sangue', '{"elemento": "Sangue", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "pessoal", "alvo": "você", "duracao": "cena", "discente": "+5 PE: Defesa +10 e resistência 5 a dano físico (3º círculo).", "verdadeiro": "+9 PE: Defesa +15 e resistência 10 (4º círculo e afinidade)."}'::jsonb, 'Carapaça de sangue: +5 em Defesa (soma com rituais, não com equipamento).', 'Livro de Regras, p. 125'),
('ritual', 'Arma Atroz', '{"elemento": "Sangue", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "toque", "alvo": "1 arma corpo a corpo", "duracao": "sustentada", "discente": "+2 PE: +5 nos ataques (2º círculo).", "verdadeiro": "+5 PE: +5 nos ataques e +2 na margem e no multiplicador (3º círculo e afinidade)."}'::jsonb, '+2 nos ataques e +1 na margem de ameaça da arma.', 'Livro de Regras, p. 125'),
('ritual', 'Canalizar o Medo', '{"elemento": "Medo", "circulo": 4, "custo_pe": 10, "execucao": "padrão", "alcance": "toque", "alvo": "1 pessoa", "duracao": "até ser descarregado"}'::jsonb, 'Empresta um ritual seu de até 3º círculo para o alvo conjurar uma vez de graça; seus PE máximos caem pelo custo até ele usar.', 'Livro de Regras, p. 125'),
('ritual', 'Capturar o Coração', '{"elemento": "Sangue", "circulo": 4, "custo_pe": 10, "execucao": "padrão", "alcance": "curto", "alvo": "1 pessoa", "duracao": "cena", "resistencia": "Vontade parcial"}'::jsonb, 'Paixão obsessiva: a cada turno, se falhar em Vontade, o alvo age para ajudá-lo. Dois sucessos seguidos encerram.', 'Livro de Regras, p. 125'),
('ritual', 'Chamas do Caos', '{"elemento": "Energia", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "curto", "alvo": "veja texto", "duracao": "cena", "discente": "+3 PE: vira sustentado; uma vez por rodada, labareda de 4d6 em alcance curto (Reflexos reduz).", "verdadeiro": "+7 PE: como discente, com 8d6 (3º círculo)."}'::jsonb, 'Escolha: arma em chamas (+1d6 de fogo), aquecer um objeto (1d6 por rodada), apagar uma chama gerando fumaça ou modelar uma chama que causa 3d6 ao passar.', 'Livro de Regras, p. 126'),
('ritual', 'Cinerária', '{"elemento": "Medo", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "curto", "alvo": "nuvem de 6m de raio", "duracao": "cena", "discente": "+2 PE: esses rituais também custam 2 PE a menos.", "verdadeiro": "+5 PE: esses rituais também causam dano máximo."}'::jsonb, 'Névoa paranormal: rituais conjurados dentro dela têm DT +5.', 'Livro de Regras, p. 126'),
('ritual', 'Cicatrização', '{"elemento": "Morte", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "toque", "alvo": "1 ser", "duracao": "instantânea", "discente": "+2 PE: 5d8+5 PV (2º círculo).", "verdadeiro": "+9 PE: alcance curto, seres escolhidos e 7d8+7 PV (4º círculo e afinidade com Morte)."}'::jsonb, 'Cura 3d8+3 PV, mas o alvo envelhece 1 ano.', 'Livro de Regras, p. 126'),
('ritual', 'Coincidência Forçada', '{"elemento": "Energia", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "curto", "alvo": "1 ser", "duracao": "cena", "discente": "+2 PE: aliados à escolha (2º círculo).", "verdadeiro": "+5 PE: aliados à escolha e bônus +5 (3º círculo e afinidade)."}'::jsonb, '+2 nos testes de perícia do alvo.', 'Livro de Regras, p. 126'),
('ritual', 'Compreensão Paranormal', '{"elemento": "Conhecimento", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "toque", "alvo": "1 ser ou objeto", "duracao": "cena", "resistencia": "Vontade anula (veja texto)", "discente": "+2 PE: alcance curto e vários alvos (2º círculo).", "verdadeiro": "+5 PE: você fala, entende e escreve qualquer idioma humano (3º círculo)."}'::jsonb, 'Entende qualquer idioma humano num texto ou gravação tocada, conversa com uma pessoa tocada ou sente emoções básicas de um animal.', 'Livro de Regras, p. 126'),
('ritual', 'Conhecendo o Medo', '{"elemento": "Medo", "circulo": 4, "custo_pe": 10, "execucao": "padrão", "alcance": "toque", "alvo": "1 pessoa", "duracao": "cena", "resistencia": "Vontade parcial"}'::jsonb, 'Falhou: Sanidade a 0 e enlouquecendo. Passou: 10d6 de dano mental e apavorado 1 rodada.', 'Livro de Regras, p. 127'),
('ritual', 'Consumir Manancial', '{"elemento": "Morte", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "pessoal", "alvo": "você", "duracao": "instantânea", "discente": "+2 PE: 6d6 PV temporários (2º círculo).", "verdadeiro": "+5 PE: esfera de 6m, 3d6 de Morte em cada ser e PV temporários iguais ao dano total (3º círculo e afinidade)."}'::jsonb, 'Suga a vida ao redor e ganha 3d6 PV temporários até o fim da cena.', 'Livro de Regras, p. 127'),
('ritual', 'Contato Paranormal', '{"elemento": "Conhecimento", "circulo": 3, "custo_pe": 6, "execucao": "completa", "alcance": "pessoal", "alvo": "você", "duracao": "1 dia", "discente": "+4 PE: dados viram d8; cada 8 custa 3 de Sanidade (4º círculo).", "verdadeiro": "+9 PE: dados viram d12; cada 12 custa 5 de Sanidade (4º círculo e afinidade)."}'::jsonb, 'Recebe seis d6 para somar a testes de perícia; cada 6 rolado custa 2 de Sanidade. Acaba sem dados ou com Sanidade 0.', 'Livro de Regras, p. 127'),
('ritual', 'Contenção Fantasmagórica', '{"elemento": "Energia", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "médio", "alvo": "1 ser", "duracao": "cena", "resistencia": "Reflexos anula", "discente": "+3 PE: 6 laços distribuídos entre alvos (3º círculo).", "verdadeiro": "+5 PE: como discente, e cada laço destruído causa 2d6+2 no preso (3º círculo e afinidade)."}'::jsonb, 'Três laços de Energia agarram o alvo; Atletismo destrói laços. Cada laço: Defesa 10, 10 PV, RD 5. Afeta incorpóreos.', 'Livro de Regras, p. 127'),
('ritual', 'Controle Mental', '{"elemento": "Conhecimento", "circulo": 4, "custo_pe": 10, "execucao": "padrão", "alcance": "médio", "alvo": "1 pessoa ou animal", "duracao": "sustentada", "resistencia": "Vontade parcial", "discente": "+5 PE: até 5 alvos.", "verdadeiro": "+10 PE: até 10 alvos (afinidade com Conhecimento)."}'::jsonb, 'O alvo obedece a todas as ordens, exceto suicidas; testa Vontade ao fim de cada turno para se livrar (fica pasmo 1 rodada).', 'Livro de Regras, p. 128'),
('ritual', 'Convocação Instantânea', '{"elemento": "Energia", "circulo": 3, "custo_pe": 6, "execucao": "padrão", "alcance": "ilimitado", "alvo": "1 objeto de até 2 espaços", "duracao": "instantânea", "resistencia": "Vontade anula", "discente": "+4 PE: objeto de até 10 espaços.", "verdadeiro": "+9 PE: um recipiente escondido no Outro Lado que você convoca à vontade (custa 1 PE permanente)."}'::jsonb, 'Traz para sua mão um objeto previamente marcado; até 1h depois pode mandá-lo de volta.', 'Livro de Regras, p. 128'),
('ritual', 'Convocar o Algoz', '{"elemento": "Morte", "circulo": 4, "custo_pe": 10, "execucao": "padrão", "alcance": "1,5m", "alvo": "1 pessoa", "duracao": "sustentada", "resistencia": "Vontade parcial, Fortitude parcial"}'::jsonb, 'Um algoz que só a vítima vê a persegue: perto, deixa abalada; adjacente, Fortitude ou cai a 0 PV (passou: 6d6 de Morte).', 'Livro de Regras, p. 128'),
('ritual', 'Corpo Adaptado', '{"elemento": "Sangue", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "toque", "alvo": "1 pessoa ou animal", "duracao": "cena", "discente": "+2 PE: dura 1 dia.", "verdadeiro": "+5 PE: alcance curto, alvos escolhidos."}'::jsonb, 'Imune a calor e frio extremos, respira na água e não sufoca em fumaça.', 'Livro de Regras, p. 128'),
('ritual', 'Decadência', '{"elemento": "Morte", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "toque", "alvo": "1 ser", "duracao": "instantânea", "resistencia": "Fortitude reduz à metade", "discente": "+2 PE: sem resistência, 3d8+3 somado a um ataque corpo a corpo.", "verdadeiro": "+5 PE: explosão de 6m de raio, 8d8+8 (3º círculo)."}'::jsonb, '2d8+2 de dano de Morte.', 'Livro de Regras, p. 129'),
('ritual', 'Definhar', '{"elemento": "Morte", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "curto", "alvo": "1 ser", "duracao": "cena", "resistencia": "Fortitude parcial", "discente": "+2 PE: exausto, ou fatigado se passar (2º círculo).", "verdadeiro": "+5 PE: como discente, até 5 seres (3º círculo e afinidade com Morte)."}'::jsonb, 'Alvo fica fatigado (ou vulnerável, se passar).', 'Livro de Regras, p. 129'),
('ritual', 'Deflagração de Energia', '{"elemento": "Energia", "circulo": 4, "custo_pe": 10, "execucao": "completa", "alcance": "pessoal", "alvo": "explosão de 15m de raio", "duracao": "instantânea", "resistencia": "Fortitude parcial", "verdadeiro": "+5 PE: só alvos escolhidos."}'::jsonb, 'Explosão de 3d10 x 10 de Energia e inutiliza itens tecnológicos (passou: metade, itens voltam em 1d4 rodadas). Você não é afetado.', 'Livro de Regras, p. 129'),
('ritual', 'Desacelerar Impacto', '{"elemento": "Morte", "circulo": 2, "custo_pe": 3, "execucao": "reação", "alcance": "curto", "alvo": "1 ser ou objetos até 10 espaços", "duracao": "até chegar ao solo ou cena", "discente": "+3 PE: até 100 espaços."}'::jsonb, 'Queda lenta sem dano; projéteis em queda causam metade do dano.', 'Livro de Regras, p. 129'),
('ritual', 'Descarnar', '{"elemento": "Sangue", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "toque", "alvo": "1 ser", "duracao": "instantânea", "resistencia": "Fortitude parcial", "discente": "+3 PE: 10d8 e hemorragia de 4d8 (3º círculo).", "verdadeiro": "+7 PE: seus ataques corpo a corpo causam +4d8 de Sangue e hemorragia (3º círculo e afinidade)."}'::jsonb, '6d8 (metade corte, metade Sangue) e hemorragia de 2d8 por turno até dois sucessos seguidos. Passou: metade, sem hemorragia.', 'Livro de Regras, p. 129'),
('ritual', 'Detecção de Ameaças', '{"elemento": "Conhecimento", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "pessoal", "alvo": "esfera de 18m de raio", "duracao": "cena", "discente": "+3 PE: não fica desprevenido contra eles e +5 contra armadilhas (3º círculo).", "verdadeiro": "+5 PE: dura 1 dia, com os benefícios de discente (4º círculo)."}'::jsonb, 'Pressente seres hostis e armadilhas na área; Percepção DT 20 revela direção e distância.', 'Livro de Regras, p. 130'),
('ritual', 'Dissipar Ritual', '{"elemento": "Medo", "circulo": 3, "custo_pe": 6, "execucao": "padrão", "alcance": "médio", "alvo": "1 ser ou objeto, ou esfera de 3m", "duracao": "instantânea"}'::jsonb, 'Teste de Ocultismo anula rituais ativos de DT igual ou menor. Num item amaldiçoado, torna-o mundano por um dia.', 'Livro de Regras, p. 130'),
('ritual', 'Dissonância Acústica', '{"elemento": "Energia", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "médio", "alvo": "esfera de 6m de raio", "duracao": "sustentada", "discente": "+1 PE: um objeto emana silêncio de 3m.", "verdadeiro": "+3 PE: dura a cena; nenhum som sai da área, mas dentro dela tudo funciona (3º círculo)."}'::jsonb, 'Todos na área ficam surdos e não podem conjurar rituais.', 'Livro de Regras, p. 130'),
('ritual', 'Distorção Temporal', '{"elemento": "Morte", "circulo": 4, "custo_pe": 10, "execucao": "padrão", "alcance": "pessoal", "alvo": "você", "duracao": "3 rodadas"}'::jsonb, 'Bolsão temporal: você age, mas não se desloca nem interage; efeitos contínuos não o afetam.', 'Livro de Regras, p. 130'),
('ritual', 'Distorcer Aparência', '{"elemento": "Sangue", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "pessoal", "alvo": "você", "duracao": "cena", "resistencia": "Vontade desacredita", "discente": "+2 PE: alcance curto, 1 ser.", "verdadeiro": "+5 PE: seres escolhidos (3º círculo)."}'::jsonb, 'Muda totalmente sua aparência: +10 em Enganação para disfarce.', 'Livro de Regras, p. 130'),
('ritual', 'Eco Espiral', '{"elemento": "Morte", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "curto", "alvo": "1 ser", "duracao": "2 rodadas", "resistencia": "Fortitude reduz à metade", "discente": "+3 PE: até 5 seres.", "verdadeiro": "+7 PE: concentra duas rodadas e descarrega na terceira (4º círculo e afinidade)."}'::jsonb, 'Concentre-se uma rodada; na seguinte, o alvo sofre de novo o dano que levou naquela rodada.', 'Livro de Regras, p. 131'),
('ritual', 'Eletrocussão', '{"elemento": "Energia", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "curto", "alvo": "1 ser ou objeto", "duracao": "instantânea", "resistencia": "Fortitude parcial", "discente": "+2 PE: linha de 30m, 6d6 (2º círculo).", "verdadeiro": "+5 PE: um raio por alvo escolhido, 8d6 cada (3º círculo)."}'::jsonb, '3d6 de eletricidade e vulnerável 1 rodada (passou: metade). Dobro em eletrônicos.', 'Livro de Regras, p. 131'),
('ritual', 'Embaralhar', '{"elemento": "Energia", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "pessoal", "alvo": "você", "duracao": "cena", "discente": "+2 PE: 5 cópias, +10 (2º círculo).", "verdadeiro": "+5 PE: 8 cópias, +16; cada cópia destruída ofusca quem a destruiu (3º círculo)."}'::jsonb, 'Três cópias ilusórias: +6 na Defesa, –2 a cada ataque que erra.', 'Livro de Regras, p. 131'),
('ritual', 'Enfeitiçar', '{"elemento": "Conhecimento", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "curto", "alvo": "1 pessoa", "duracao": "cena", "resistencia": "Vontade anula", "discente": "+2 PE: o alvo cumpre uma sugestão aceitável (2º círculo).", "verdadeiro": "+5 PE: afeta todos no alcance (3º círculo)."}'::jsonb, 'Alvo fica prestativo e você ganha +10 em Diplomacia com ele; termina se houver hostilidade.', 'Livro de Regras, p. 131'),
('ritual', 'Esconder dos Olhos', '{"elemento": "Conhecimento", "circulo": 2, "custo_pe": 3, "execucao": "livre", "alcance": "pessoal", "alvo": "você", "duracao": "1 rodada", "discente": "+3 PE: sustentado, esfera de invisibilidade de 3m para você e aliados (3º círculo).", "verdadeiro": "+7 PE: toca 1 ser, sustentado, não acaba ao atacar (4º círculo e afinidade)."}'::jsonb, 'Invisível: camuflagem total e +15 em Furtividade; acaba ao atacar.', 'Livro de Regras, p. 132'),
('ritual', 'Espirais da Perdição', '{"elemento": "Morte", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "curto", "alvo": "1 ser", "duracao": "cena", "discente": "+2 PE: –2 dados (2º círculo).", "verdadeiro": "+8 PE: –2 dados em seres escolhidos (3º círculo)."}'::jsonb, 'Alvo sofre –1 dado nos testes de ataque.', 'Livro de Regras, p. 133'),
('ritual', 'Ferver Sangue', '{"elemento": "Sangue", "circulo": 3, "custo_pe": 6, "execucao": "padrão", "alcance": "curto", "alvo": "1 ser", "duracao": "sustentada", "resistencia": "Fortitude parcial", "verdadeiro": "+4 PE: seres escolhidos (4º círculo e afinidade)."}'::jsonb, 'A cada turno, 4d8 de Sangue e fraco (passou: metade). Dois sucessos seguidos encerram.', 'Livro de Regras, p. 133'),
('ritual', 'Fim Inevitável', '{"elemento": "Morte", "circulo": 4, "custo_pe": 10, "execucao": "completa", "alcance": "extremo", "alvo": "buraco negro de 1,5m", "duracao": "4 rodadas", "resistencia": "Fortitude parcial", "discente": "+5 PE: 5 rodadas e você não é afetado (afinidade).", "verdadeiro": "+10 PE: 6 rodadas e seres escolhidos não são afetados (afinidade)."}'::jsonb, 'Vácuo puxa todos a até 90m (inclusive você) 30m por rodada; tocar nele causa 100 de Morte por rodada.', 'Livro de Regras, p. 133'),
('ritual', 'Flagelo de Sangue', '{"elemento": "Sangue", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "toque", "alvo": "1 pessoa", "duracao": "cena", "resistencia": "Fortitude parcial", "discente": "+3 PE: qualquer ser exceto criaturas de Sangue (3º círculo).", "verdadeiro": "+7 PE: como discente, dura 1 dia (4º círculo e afinidade)."}'::jsonb, 'Marca com uma ordem; cada rodada desobedecida causa 10d6 de Sangue e enjoo (passou: metade). Dois sucessos seguidos apagam a marca.', 'Livro de Regras, p. 133'),
('ritual', 'Forma Monstruosa', '{"elemento": "Sangue", "circulo": 3, "custo_pe": 6, "execucao": "padrão", "alcance": "pessoal", "alvo": "você", "duracao": "cena", "discente": "+3 PE: imune a atordoamento, fadiga, sangramento, sono e veneno (3º círculo).", "verdadeiro": "+9 PE: bônus +10 e 50 PV temporários (4º círculo e afinidade)."}'::jsonb, 'Vira Grande: +5 em ataque e dano corpo a corpo e 30 PV temporários, mas em fúria (não fala nem conjura, ataca o mais próximo).', 'Livro de Regras, p. 133'),
('ritual', 'Fortalecimento Sensorial', '{"elemento": "Sangue", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "pessoal", "alvo": "você", "duracao": "cena", "discente": "+2 PE: inimigos sofrem –1 dado para atacá-lo (2º círculo).", "verdadeiro": "+5 PE: imune a surpreendido e desprevenido, +10 em Defesa e Reflexos (4º círculo e afinidade)."}'::jsonb, '+1 dado em Investigação, Luta, Percepção e Pontaria.', 'Livro de Regras, p. 133'),
('ritual', 'Hemofagia', '{"elemento": "Sangue", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "toque", "alvo": "1 ser", "duracao": "instantânea", "resistencia": "Fortitude reduz à metade", "discente": "+3 PE: sem resistência, somado a um ataque corpo a corpo.", "verdadeiro": "+7 PE: dura a cena; a cada rodada, toque causa 4d6 e cura metade (4º círculo)."}'::jsonb, '6d6 de Sangue e você cura metade do dano causado.', 'Livro de Regras, p. 133'),
('ritual', 'Inexistir', '{"elemento": "Conhecimento", "circulo": 4, "custo_pe": 10, "execucao": "padrão", "alcance": "toque", "alvo": "1 ser", "duracao": "instantânea", "resistencia": "Vontade parcial", "discente": "+5 PE: 15d12+15 (3d12 se passar).", "verdadeiro": "+10 PE: 20d12+20 (4d12 se passar) (afinidade)."}'::jsonb, '10d12+10 de Conhecimento (passou: 2d12 e debilitado). Quem chega a 0 PV é apagado da existência.', 'Livro de Regras, p. 134'),
('ritual', 'Invadir Mente', '{"elemento": "Conhecimento", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "médio ou toque", "alvo": "1 ser ou 2 pessoas voluntárias", "duracao": "instantânea ou 1 dia", "resistencia": "Vontade parcial ou nenhuma", "discente": "+3 PE: rajada de 10d6, ou ver e ouvir pelos sentidos do alvo (3º círculo).", "verdadeiro": "+7 PE: rajada de 10d6 em seres escolhidos, ou ligação entre até 5 pessoas."}'::jsonb, 'Rajada mental (6d6 de Conhecimento e atordoado) ou ligação telepática entre duas pessoas por 1 dia.', 'Livro de Regras, p. 134'),
('ritual', 'Invólucro de Carne', '{"elemento": "Sangue", "circulo": 4, "custo_pe": 10, "execucao": "padrão", "alcance": "curto", "alvo": "1 clone seu", "duracao": "cena"}'::jsonb, 'Cria uma cópia sua com as mesmas estatísticas, que segue ordens ou pode ser controlada diretamente.', 'Livro de Regras, p. 135'),
('ritual', 'Lâmina do Medo', '{"elemento": "Medo", "circulo": 4, "custo_pe": 10, "execucao": "padrão", "alcance": "toque", "alvo": "1 ser", "duracao": "instantânea", "resistencia": "Fortitude parcial"}'::jsonb, 'Falhou: 0 PV e morrendo. Passou: 10d8 de Medo (ignora resistências) e apavorado. Exige poder de trilha específico.', 'Livro de Regras, p. 135'),
('ritual', 'Localização', '{"elemento": "Conhecimento", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "pessoal", "alvo": "círculo de 90m de raio", "duracao": "cena", "discente": "+3 PE: a pessoa tocada sabe o caminho mais direto para entrar ou sair de um lugar.", "verdadeiro": "+7 PE: raio de 1km (4º círculo)."}'::jsonb, 'Indica direção e distância da pessoa ou objeto mais próximo do tipo pensado. Chumbo bloqueia.', 'Livro de Regras, p. 135'),
('ritual', 'Luz', '{"elemento": "Energia", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "curto", "alvo": "1 objeto", "duracao": "cena", "resistencia": "Vontade anula (veja texto)", "discente": "+2 PE: 4 esferas de luz móveis em alcance longo, que ofuscam e revelam (2º círculo).", "verdadeiro": "+5 PE: luz solar: aliados +1 dado em Vontade, inimigos ofuscados (3º círculo)."}'::jsonb, 'O objeto ilumina 9m de raio com cores alternadas.', 'Livro de Regras, p. 135'),
('ritual', 'Medo Tangível', '{"elemento": "Medo", "circulo": 4, "custo_pe": 10, "execucao": "padrão", "alcance": "pessoal", "alvo": "você", "duracao": "cena"}'::jsonb, 'Imune a várias condições, doenças, venenos e críticos; dano físico comum não o leva abaixo de 1 PV.', 'Livro de Regras, p. 135'),
('ritual', 'Mergulho Mental', '{"elemento": "Conhecimento", "circulo": 3, "custo_pe": 6, "execucao": "padrão", "alcance": "toque", "alvo": "1 pessoa", "duracao": "sustentada", "resistencia": "Vontade parcial (veja texto)", "verdadeiro": "+4 PE: feito à distância com uma cuba de ouro e máscara, se tiver nome e objeto do alvo (4º círculo)."}'::jsonb, 'A cada turno, se falhar em Vontade, o alvo responde com verdade a uma pergunta de sim ou não. Você fica desprevenido.', 'Livro de Regras, p. 136'),
('ritual', 'Miasma Entrópico', '{"elemento": "Morte", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "médio", "alvo": "nuvem de 6m de raio", "duracao": "instantânea", "resistencia": "Fortitude parcial", "discente": "+3 PE: 6d8 de Morte.", "verdadeiro": "+7 PE: dura 3 rodadas, repetindo o dano (3º círculo)."}'::jsonb, '4d8 de dano químico e enjoado 1 rodada (passou: metade).', 'Livro de Regras, p. 136'),
('ritual', 'Nuvem de Cinzas', '{"elemento": "Morte", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "curto", "alvo": "nuvem de 6m de raio e 6m de altura", "duracao": "cena", "discente": "+2 PE: seres escolhidos enxergam através (2º círculo).", "verdadeiro": "+5 PE: nuvem quase sólida, deslocamento 3m e –2 nos ataques (3º círculo)."}'::jsonb, 'Fuligem que dá camuflagem a quem está perto e camuflagem total a partir de 3m.', 'Livro de Regras, p. 136'),
('ritual', 'Ódio Incontrolável', '{"elemento": "Sangue", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "toque", "alvo": "1 pessoa", "duracao": "cena", "discente": "+2 PE: um ataque corpo a corpo extra ao agredir.", "verdadeiro": "+5 PE: bônus +5 e metade do dano físico (3º círculo e afinidade)."}'::jsonb, '+2 em ataque e dano corpo a corpo e resistência 5 a dano físico, mas sem ações calmas e obrigado a atacar.', 'Livro de Regras, p. 137'),
('ritual', 'Ouvir os Sussurros', '{"elemento": "Conhecimento", "circulo": 1, "custo_pe": 1, "execucao": "completa", "alcance": "pessoal", "alvo": "você", "duracao": "instantânea", "discente": "+2 PE: pergunta sobre algo até um dia à frente, com resposta em pista ou enigma (2º círculo).", "verdadeiro": "+5 PE: uma pergunta por rodada durante 5 rodadas (3º círculo)."}'::jsonb, 'Pergunta de sim ou não sobre uma ação desta cena; o mestre rola 1d6 em segredo (no 1, resposta “não”).', 'Livro de Regras, p. 137'),
('ritual', 'Paradoxo', '{"elemento": "Morte", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "médio", "alvo": "esfera de 6m de raio", "duracao": "instantânea", "resistencia": "Fortitude reduz à metade", "discente": "+3 PE: esfera móvel de 1,5m que causa 4d6 por onde passa (dura a cena).", "verdadeiro": "+7 PE: 13d6; quem cai a 0 PV e falha em Fortitude vira cinzas (4º círculo)."}'::jsonb, '6d6 de Morte em todos na área.', 'Livro de Regras, p. 137'),
('ritual', 'Perturbação', '{"elemento": "Conhecimento", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "curto", "alvo": "1 pessoa", "duracao": "1 rodada", "resistencia": "Vontade anula", "discente": "+2 PE: qualquer ser e a ordem “Sofra” (3d8 de Conhecimento e abalado).", "verdadeiro": "+5 PE: até 5 seres, ou a ordem “Ataque” contra outro alvo (3º círculo e afinidade)."}'::jsonb, 'Uma ordem que o alvo obedece no turno dele: Fuja, Largue, Pare, Sente-se ou Venha.', 'Livro de Regras, p. 137'),
('ritual', 'Poeira da Podridão', '{"elemento": "Morte", "circulo": 3, "custo_pe": 6, "execucao": "padrão", "alcance": "médio", "alvo": "nuvem de 6m de raio", "duracao": "sustentada", "resistencia": "Fortitude (veja texto)", "verdadeiro": "+4 PE: 4d8+16."}'::jsonb, 'A cada turno, 4d8 de Morte (Fortitude reduz); quem falha não recupera PV por 1 rodada.', 'Livro de Regras, p. 138'),
('ritual', 'Polarização Caótica', '{"elemento": "Energia", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "curto", "alvo": "você", "duracao": "sustentada", "resistencia": "Vontade anula", "discente": "+2 PE: arremessa até 10 objetos de uma vez, causando dano por espaço.", "verdadeiro": "+5 PE: alcance médio, levita e move um ser ou objeto de até 10 espaços."}'::jsonb, 'Aura magnética: atrai objetos metálicos pequenos ou repele projéteis (resistência 5 a dano físico).', 'Livro de Regras, p. 138'),
('ritual', 'Possessão', '{"elemento": "Conhecimento", "circulo": 4, "custo_pe": 10, "execucao": "padrão", "alcance": "longo", "alvo": "1 pessoa viva ou morta", "duracao": "1 dia", "resistencia": "Vontade anula"}'::jsonb, 'Assume o corpo do alvo, usando os atributos físicos e o deslocamento dele.', 'Livro de Regras, p. 139'),
('ritual', 'Presença do Medo', '{"elemento": "Medo", "circulo": 4, "custo_pe": 10, "execucao": "padrão", "alcance": "pessoal", "alvo": "emanação de 9m de raio", "duracao": "sustentada", "resistencia": "Vontade reduz à metade"}'::jsonb, 'A cada turno, 5d8 de dano mental e 5d8 de Medo na área; falhar atordoa uma vez por cena.', 'Livro de Regras, p. 139'),
('ritual', 'Proteção contra Rituais', '{"elemento": "Medo", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "toque", "alvo": "1 ser", "duracao": "cena", "discente": "+3 PE: até 5 seres (3º círculo).", "verdadeiro": "+6 PE: até 5 seres, resistência 10 e +10 (4º círculo)."}'::jsonb, 'Resistência 5 a dano paranormal e +5 em resistência contra rituais e habilidades paranormais.', 'Livro de Regras, p. 139'),
('ritual', 'Purgatório', '{"elemento": "Sangue", "circulo": 3, "custo_pe": 6, "execucao": "padrão", "alcance": "curto", "alvo": "área de 6m de raio", "duracao": "sustentada", "resistencia": "Fortitude parcial"}'::jsonb, 'Poça de sangue: inimigos ficam vulneráveis a dano físico e sair dela causa 6d6 e pode prender.', 'Livro de Regras, p. 139'),
('ritual', 'Rejeitar Névoa', '{"elemento": "Medo", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "curto", "alvo": "nuvem de 6m de raio", "duracao": "cena", "discente": "+2 PE: DT de resistência contra rituais na área cai 5.", "verdadeiro": "+5 PE: como discente, e rituais na área causam dano mínimo."}'::jsonb, 'Rituais na área custam +2 PE por círculo e demoram um passo a mais para executar. Anula Cinerária.', 'Livro de Regras, p. 139'),
('ritual', 'Salto Fantasma', '{"elemento": "Energia", "circulo": 3, "custo_pe": 6, "execucao": "padrão", "alcance": "médio", "alvo": "você", "duracao": "instantânea", "discente": "+2 PE: como reação, salta 1,5m e ganha +10 em Defesa e Reflexos contra um ataque.", "verdadeiro": "+4 PE: alcance longo, leva até dois seres tocados."}'::jsonb, 'Teleporta para um ponto que já tenha visto (mesmo sem linha de visão); não age mais no turno.', 'Livro de Regras, p. 139'),
('ritual', 'Sopro do Caos', '{"elemento": "Energia", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "médio", "alvo": "varia", "duracao": "sustentada", "discente": "+3 PE: afeta alvos Grandes.", "verdadeiro": "+9 PE: afeta alvos Enormes."}'::jsonb, 'Controla o ar: fazer um ser flutuar, empurrar num cone (Ocultismo no lugar de Luta) ou criar vento forte.', 'Livro de Regras, p. 140'),
('ritual', 'Tecer Ilusão', '{"elemento": "Conhecimento", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "médio", "alvo": "ilusão de até 4 cubos de 1,5m", "duracao": "cena", "resistencia": "Vontade desacredita", "discente": "+2 PE: 8 cubos, imagem e som juntos, móvel e mais convincente (2º círculo).", "verdadeiro": "+5 PE: ilusão de perigo mortal que causa 6d6 de Conhecimento a quem acredita (3º círculo)."}'::jsonb, 'Ilusão simples visual ou sonora; não causa dano.', 'Livro de Regras, p. 140'),
('ritual', 'Tela de Ruído', '{"elemento": "Energia", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "pessoal", "alvo": "você", "duracao": "cena", "discente": "+3 PE: 60 PV temporários ou resistência 30.", "verdadeiro": "+7 PE: esfera impenetrável em volta de um ser ou objeto em alcance curto (4º círculo)."}'::jsonb, '30 PV temporários só contra dano físico; ou, como reação, resistência 15 contra um dano.', 'Livro de Regras, p. 141'),
('ritual', 'Teletransporte', '{"elemento": "Energia", "circulo": 4, "custo_pe": 10, "execucao": "padrão", "alcance": "toque", "alvo": "até 5 seres voluntários", "duracao": "instantânea", "verdadeiro": "+5 PE: qualquer lugar da Terra."}'::jsonb, 'Leva os alvos a até 1.000km; Ocultismo DT 25 a 35 conforme você conhece o destino.', 'Livro de Regras, p. 141'),
('ritual', 'Tentáculos de Lodo', '{"elemento": "Morte", "circulo": 3, "custo_pe": 6, "execucao": "padrão", "alcance": "médio", "alvo": "círculo de 6m de raio", "duracao": "cena", "verdadeiro": "+5 PE: raio de 9m e 6d6."}'::jsonb, 'A cada turno, tenta agarrar todos na área (Ocultismo no lugar de Luta); agarrados sofrem 4d6. Terreno difícil.', 'Livro de Regras, p. 141'),
('ritual', 'Terceiro Olho', '{"elemento": "Conhecimento", "circulo": 1, "custo_pe": 1, "execucao": "padrão", "alcance": "pessoal", "alvo": "você", "duracao": "cena", "discente": "+2 PE: dura 1 dia.", "verdadeiro": "+5 PE: também vê seres e objetos invisíveis."}'::jsonb, 'Enxerga auras paranormais em alcance longo, com elemento e força aproximada.', 'Livro de Regras, p. 141'),
('ritual', 'Transfigurar Água', '{"elemento": "Energia", "circulo": 3, "custo_pe": 6, "execucao": "padrão", "alcance": "longo", "alvo": "esfera de 30m de raio", "duracao": "cena", "resistencia": "veja texto", "verdadeiro": "+5 PE: enchente mais forte e evaporar com 10d8."}'::jsonb, 'Congelar, derreter, enchente, evaporar (5d8 de Energia em seres vivos) ou partir a água.', 'Livro de Regras, p. 142'),
('ritual', 'Transfigurar Terra', '{"elemento": "Energia", "circulo": 3, "custo_pe": 6, "execucao": "padrão", "alcance": "longo", "alvo": "9 cubos de 1,5m", "duracao": "instantânea", "resistencia": "veja texto", "discente": "+3 PE: 15 cubos.", "verdadeiro": "+7 PE: também afeta minerais e metais (4º círculo)."}'::jsonb, 'Amolecer (pode desabar: 10d6), modelar objetos e paredes, ou solidificar e prender.', 'Livro de Regras, p. 142'),
('ritual', 'Transfusão Vital', '{"elemento": "Sangue", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "toque", "alvo": "1 ser", "duracao": "instantânea", "discente": "+3 PE: até 50 (3º círculo).", "verdadeiro": "+7 PE: até 100 (4º círculo)."}'::jsonb, 'Você sofre até 30 de dano de Sangue e o alvo cura o mesmo (você não cai abaixo de 1 PV).', 'Livro de Regras, p. 143'),
('ritual', 'Velocidade Mortal', '{"elemento": "Morte", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "curto", "alvo": "1 ser", "duracao": "sustentada", "discente": "+3 PE: uma ação padrão extra.", "verdadeiro": "+7 PE: alvos escolhidos (4º círculo e afinidade)."}'::jsonb, 'Uma ação de movimento extra por turno (não serve para rituais).', 'Livro de Regras, p. 143'),
('ritual', 'Vidência', '{"elemento": "Conhecimento", "circulo": 3, "custo_pe": 6, "execucao": "completa", "alcance": "ilimitado", "alvo": "1 ser", "duracao": "5 rodadas", "resistencia": "Vontade anula"}'::jsonb, 'Vê e ouve o alvo por uma superfície refletora; o quanto você o conhece muda o teste dele.', 'Livro de Regras, p. 143'),
('ritual', 'Vínculo de Sangue', '{"elemento": "Sangue", "circulo": 4, "custo_pe": 10, "execucao": "padrão", "alcance": "curto", "alvo": "1 ser", "duracao": "cena", "resistencia": "Fortitude anula"}'::jsonb, 'Quando você sofre dano, o alvo testa Fortitude; se falhar, divide o dano com você.', 'Livro de Regras, p. 143'),
('ritual', 'Vomitar Pestes', '{"elemento": "Sangue", "circulo": 3, "custo_pe": 6, "execucao": "padrão", "alcance": "médio", "alvo": "1 enxame Grande", "duracao": "sustentada", "resistencia": "Reflexos reduz à metade", "discente": "+2 PE: quem falha fica agarrado pelo enxame.", "verdadeiro": "+5 PE: enxame Enorme e voador."}'::jsonb, 'Enxame móvel que causa 5d12 de Sangue a quem estiver no espaço dele.', 'Livro de Regras, p. 143'),
('ritual', 'Zerar Entropia', '{"elemento": "Morte", "circulo": 3, "custo_pe": 6, "execucao": "padrão", "alcance": "curto", "alvo": "1 pessoa", "duracao": "cena", "resistencia": "Vontade parcial", "discente": "+4 PE: qualquer ser (4º círculo).", "verdadeiro": "+11 PE: seres escolhidos (4º círculo e afinidade)."}'::jsonb, 'Alvo fica paralisado (lento, se passar); pode gastar ação completa para testar de novo.', 'Livro de Regras, p. 143'),
('maldicao', 'Antielemento', '{"elemento": "Conhecimento", "subtipo": "Maldição para armas"}'::jsonb, 'Contra criaturas de um elemento, 2 PE por ataque: +4d8 de dano se acertar.', 'Livro de Regras, p. 145'),
('maldicao', 'Ritualística', '{"elemento": "Conhecimento", "subtipo": "Maldição para armas"}'::jsonb, 'Guarda um ritual pago antes; ao acertar, descarrega no alvo como ação livre.', 'Livro de Regras, p. 145'),
('maldicao', 'Senciente', '{"elemento": "Conhecimento", "subtipo": "Maldição para armas"}'::jsonb, 'Movimento e 2 PE: a arma flutua e ataca sozinha uma vez por rodada (1 PE por turno para manter).', 'Livro de Regras, p. 146'),
('maldicao', 'Lancinante', '{"elemento": "Sangue", "subtipo": "Maldição para armas"}'::jsonb, '+1d8 de dano de Sangue, multiplicado no crítico.', 'Livro de Regras, p. 146'),
('maldicao', 'Predadora', '{"elemento": "Sangue", "subtipo": "Maldição para armas"}'::jsonb, 'Ignora camuflagem e cobertura parcial, aumenta o alcance e dobra a margem de ameaça.', 'Livro de Regras, p. 146'),
('maldicao', 'Sanguinária', '{"elemento": "Sangue", "subtipo": "Maldição para armas"}'::jsonb, 'Deixa o alvo sangrando (acumula); no crítico, o alvo fica fraco e você ganha 2d10 PV temporários.', 'Livro de Regras, p. 146'),
('maldicao', 'Empuxo', '{"elemento": "Energia", "subtipo": "Maldição para armas"}'::jsonb, 'Arma corpo a corpo pode ser arremessada com um dado extra de dano e volta para sua mão.', 'Livro de Regras, p. 146'),
('maldicao', 'Energética', '{"elemento": "Energia", "subtipo": "Maldição para armas"}'::jsonb, '2 PE por ataque: +5 no ataque, ignora resistência e o dano vira Energia.', 'Livro de Regras, p. 146'),
('maldicao', 'Vibrante', '{"elemento": "Energia", "subtipo": "Maldição para armas"}'::jsonb, 'Concede Ataque Extra (ou reduz o custo dele em 1 PE).', 'Livro de Regras, p. 146'),
('maldicao', 'Consumidora', '{"elemento": "Morte", "subtipo": "Maldição para armas"}'::jsonb, 'Alvos atingidos ficam lentos; 2 PE ao atacar deixam o alvo imóvel 1 rodada.', 'Livro de Regras, p. 146'),
('maldicao', 'Erosiva', '{"elemento": "Morte", "subtipo": "Maldição para armas"}'::jsonb, '+1d8 de Morte; 2 PE ao atacar causam 2d4 de Morte por duas rodadas.', 'Livro de Regras, p. 146'),
('maldicao', 'Repulsora', '{"elemento": "Morte", "subtipo": "Maldição para armas"}'::jsonb, '+2 de Defesa empunhada; ao bloquear, 2 PE dão +5 de Defesa.', 'Livro de Regras, p. 147'),
('maldicao', 'Abascanta', '{"elemento": "Conhecimento", "subtipo": "Maldição para proteções"}'::jsonb, '+5 contra rituais; uma vez por cena, reflete um ritual pagando o custo dele.', 'Livro de Regras, p. 146'),
('maldicao', 'Profética', '{"elemento": "Conhecimento", "subtipo": "Maldição para proteções"}'::jsonb, 'Resistência a Conhecimento 10 e 2 PE para rolar de novo um teste de resistência.', 'Livro de Regras, p. 147'),
('maldicao', 'Sombria', '{"elemento": "Conhecimento", "subtipo": "Maldição para proteções"}'::jsonb, '+5 em Furtividade sem penalidade de carga; pode parecer roupa comum.', 'Livro de Regras, p. 147'),
('maldicao', 'Cinética', '{"elemento": "Energia", "subtipo": "Maldição para proteções"}'::jsonb, '+2 de Defesa e resistência a dano 2 (leve ou escudo) ou 5 (pesada).', 'Livro de Regras, p. 147'),
('maldicao', 'Lépida', '{"elemento": "Energia", "subtipo": "Maldição para proteções"}'::jsonb, '+10 em Atletismo e +3m de deslocamento; 2 PE para escalar, ignorar terreno difícil e quedas até 9m.', 'Livro de Regras, p. 147'),
('maldicao', 'Voltaica', '{"elemento": "Energia", "subtipo": "Maldição para proteções"}'::jsonb, 'Resistência a Energia 10; 2 PE para causar 2d6 de Energia em quem estiver adjacente a cada turno.', 'Livro de Regras, p. 147'),
('maldicao', 'Letárgica', '{"elemento": "Morte", "subtipo": "Maldição para proteções"}'::jsonb, '+2 de Defesa e chance de ignorar dano extra de crítico e ataque furtivo.', 'Livro de Regras, p. 147'),
('maldicao', 'Repulsiva', '{"elemento": "Morte", "subtipo": "Maldição para proteções"}'::jsonb, 'Resistência a Morte 10; 2 PE para que atacantes corpo a corpo sofram 2d8 de Morte.', 'Livro de Regras, p. 147'),
('maldicao', 'Regenerativa', '{"elemento": "Sangue", "subtipo": "Maldição para proteções"}'::jsonb, 'Resistência a Sangue 10; movimento e 1 PE para curar 1d12 PV.', 'Livro de Regras, p. 147'),
('maldicao', 'Sádica', '{"elemento": "Sangue", "subtipo": "Maldição para proteções"}'::jsonb, '+1 em ataque e dano para cada 10 de dano sofrido desde seu último turno.', 'Livro de Regras, p. 147'),
('maldicao', 'Carisma', '{"elemento": "Conhecimento", "subtipo": "Maldição para acessórios"}'::jsonb, '+1 em Presença (não dá PE).', 'Livro de Regras, p. 147'),
('maldicao', 'Conjuração', '{"elemento": "Conhecimento", "subtipo": "Maldição para acessórios"}'::jsonb, 'Permite conjurar um ritual de 1º círculo (ou reduz o custo dele em 1 PE).', 'Livro de Regras, p. 147'),
('maldicao', 'Escudo Mental', '{"elemento": "Conhecimento", "subtipo": "Maldição para acessórios"}'::jsonb, 'Resistência mental 10.', 'Livro de Regras, p. 147'),
('maldicao', 'Reflexão', '{"elemento": "Conhecimento", "subtipo": "Maldição para acessórios"}'::jsonb, 'Uma vez por rodada, reflete um ritual pagando o custo dele.', 'Livro de Regras, p. 147'),
('maldicao', 'Sagacidade', '{"elemento": "Conhecimento", "subtipo": "Maldição para acessórios"}'::jsonb, '+1 em Intelecto (não dá perícias).', 'Livro de Regras, p. 147'),
('maldicao', 'Defesa', '{"elemento": "Energia", "subtipo": "Maldição para acessórios"}'::jsonb, '+5 de Defesa.', 'Livro de Regras, p. 147'),
('maldicao', 'Destreza', '{"elemento": "Energia", "subtipo": "Maldição para acessórios"}'::jsonb, '+1 em Agilidade.', 'Livro de Regras, p. 147'),
('maldicao', 'Potência', '{"elemento": "Energia", "subtipo": "Maldição para acessórios"}'::jsonb, '+1 na DT dos seus rituais e habilidades.', 'Livro de Regras, p. 147'),
('maldicao', 'Esforço Adicional', '{"elemento": "Morte", "subtipo": "Maldição para acessórios"}'::jsonb, '+5 PE após um dia de uso.', 'Livro de Regras, p. 147'),
('maldicao', 'Disposição', '{"elemento": "Sangue", "subtipo": "Maldição para acessórios"}'::jsonb, '+1 em Vigor.', 'Livro de Regras, p. 147'),
('maldicao', 'Pujança', '{"elemento": "Sangue", "subtipo": "Maldição para acessórios"}'::jsonb, '+1 em Força.', 'Livro de Regras, p. 147'),
('maldicao', 'Vitalidade', '{"elemento": "Sangue", "subtipo": "Maldição para acessórios"}'::jsonb, '+15 PV após um dia de uso.', 'Livro de Regras, p. 147'),
('maldicao', 'Proteção Elemental', '{"elemento": "Varia", "subtipo": "Maldição para acessórios"}'::jsonb, 'Resistência 10 contra um elemento.', 'Livro de Regras, p. 147'),
('item_amaldicoado', 'Pérola de Sangue', '{"elemento": "Sangue", "categoria": "II", "espacos": 1}'::jsonb, 'Absorver: +5 em testes de Agilidade, Força e Vigor na cena; depois, Fortitude DT 20 ou fadiga (ou pior).', 'Livro de Regras, p. 148'),
('item_amaldicoado', 'Coração Pulsante', '{"elemento": "Sangue", "categoria": "II", "espacos": 1}'::jsonb, 'Reação: reduz um dano à metade; Fortitude crescente a cada uso ou o coração é destruído.', 'Livro de Regras, p. 148'),
('item_amaldicoado', 'Coroa de Espinhos', '{"elemento": "Sangue", "categoria": "II", "espacos": 1}'::jsonb, 'Reação: transforma dano mental em dano de Sangue, mas impede recuperar Sanidade descansando.', 'Livro de Regras, p. 148'),
('item_amaldicoado', 'Frasco de Vitalidade', '{"elemento": "Sangue", "categoria": "II", "espacos": 1}'::jsonb, 'Guarda até 20 PV do seu próprio sangue para beber depois (pode enjoar).', 'Livro de Regras, p. 148'),
('item_amaldicoado', 'Punhos Enraivecidos', '{"elemento": "Sangue", "categoria": "II", "espacos": 1}'::jsonb, 'Desarmado causa 1d8 de Sangue; cada acerto permite outro ataque pagando PE crescente.', 'Livro de Regras, p. 149'),
('item_amaldicoado', 'Seringa de Transfiguração', '{"elemento": "Sangue", "categoria": "II", "espacos": 1}'::jsonb, 'Coleta sangue de alguém e dá a aparência dessa pessoa a outra por um dia.', 'Livro de Regras, p. 149'),
('item_amaldicoado', 'Amarras Mortais', '{"elemento": "Morte", "categoria": "II", "espacos": 1}'::jsonb, 'Ação padrão e 2 PE: agarrar em alcance curto com +10, e puxar o alvo para perto.', 'Livro de Regras, p. 149'),
('item_amaldicoado', 'Casaco de Lodo', '{"elemento": "Morte", "categoria": "II", "espacos": 1}'::jsonb, 'Resistência 5 a corte, impacto, Morte e perfuração, mas vulnerável a balístico e Energia.', 'Livro de Regras, p. 149'),
('item_amaldicoado', 'Coletora', '{"elemento": "Morte", "categoria": "II", "espacos": 1}'::jsonb, 'Punhal que mata quem está morrendo e guarda 1d8 PE (até 20) para você usar; causa pesadelos.', 'Livro de Regras, p. 149'),
('item_amaldicoado', 'Crânio Espiral', '{"elemento": "Morte", "categoria": "II", "espacos": 1}'::jsonb, 'Ação livre: uma ação padrão extra na rodada; Vontade crescente ou envelhece 1d4 anos.', 'Livro de Regras, p. 149'),
('item_amaldicoado', 'Vislumbre do Fim', '{"elemento": "Morte", "categoria": "II", "espacos": 1}'::jsonb, 'Óculos que mostram o tempo de vida de pessoas comuns, ou a pior resistência e as vulnerabilidades de criaturas.', 'Livro de Regras, p. 149'),
('item_amaldicoado', 'Anéis do Elo Mental', '{"elemento": "Conhecimento", "categoria": "II", "espacos": 1}'::jsonb, 'Dois usuários ficam ligados por telepatia e compartilham Vontade, dano mental e condições de medo.', 'Livro de Regras, p. 149'),
('item_amaldicoado', 'Lanterna Reveladora', '{"elemento": "Conhecimento", "categoria": "II", "espacos": 1}'::jsonb, '1 PE: luz com os efeitos de Terceiro Olho por uma cena; atrai criaturas de Sangue.', 'Livro de Regras, p. 149'),
('item_amaldicoado', 'Frasco de Lodo', '{"elemento": "Morte", "categoria": "II", "espacos": 1}'::jsonb, 'Em ferida recente cura 6d8+20; em ferida antiga pode curar ou infeccionar. Uso único.', 'Livro de Regras, p. 149'),
('item_amaldicoado', 'Máscara das Pessoas nas Sombras', '{"elemento": "Conhecimento", "categoria": "II", "espacos": 1}'::jsonb, 'Resistência a Conhecimento 10 e 2 PE para viajar entre sombras em alcance médio.', 'Livro de Regras, p. 149'),
('item_amaldicoado', 'Munição Jurada', '{"elemento": "Conhecimento", "categoria": "II", "espacos": 1}'::jsonb, 'Bala vinculada a um ser: +10 no ataque, margem dobrada e +6d12; obsessão pelo alvo.', 'Livro de Regras, p. 150'),
('item_amaldicoado', 'Pergaminho da Pertinácia', '{"elemento": "Conhecimento", "categoria": "II", "espacos": 1}'::jsonb, 'Ação padrão: 5 PE temporários na cena; Ocultismo crescente ou se desfaz.', 'Livro de Regras, p. 150'),
('item_amaldicoado', 'Arcabuz dos Moretti', '{"elemento": "Energia", "categoria": "II", "espacos": 1}'::jsonb, 'Arma de fogo simples de uma mão, +2 no ataque, dano sorteado por 1d6 (de 2d4 a 2d20), sem munição.', 'Livro de Regras, p. 150'),
('item_amaldicoado', 'Bateria Reversa', '{"elemento": "Energia", "categoria": "II", "espacos": 1}'::jsonb, 'Descarrega ou recarrega aparelhos em alcance curto; pode explodir (12d6).', 'Livro de Regras, p. 150'),
('item_amaldicoado', 'Peitoral da Segunda Chance', '{"elemento": "Energia", "categoria": "II", "espacos": 1}'::jsonb, 'Ao chegar a 0 PV, gasta 5 PE e reanima com 4d10 PV; pequena chance de matar na hora.', 'Livro de Regras, p. 151'),
('item_amaldicoado', 'Relógio de Arnaldo', '{"elemento": "Energia", "categoria": "II", "espacos": 1}'::jsonb, '1 PE (crescente no dia) para rolar de novo um dado com resultado 1.', 'Livro de Regras, p. 151'),
('item_amaldicoado', 'Talismã da Sorte', '{"elemento": "Energia", "categoria": "II", "espacos": 1}'::jsonb, 'Reação e 3 PE ao sofrer dano: 1d4 decide se evita o dano ou dobra.', 'Livro de Regras, p. 151'),
('item_amaldicoado', 'Teclado de Conexão Neural', '{"elemento": "Energia", "categoria": "II", "espacos": 1}'::jsonb, 'Liga sua mente ao computador: +10 para hackear e metade do tempo, mas 1d6 de dano mental por rodada.', 'Livro de Regras, p. 151'),
('item_amaldicoado', 'Tela do Pesadelo', '{"elemento": "Energia", "categoria": "II", "espacos": 1}'::jsonb, '2 PE: quem tocar a tela vê uma ilusão aterradora (atordoado e 4d6 de dano mental até passar).', 'Livro de Regras, p. 151'),
('item_amaldicoado', 'Veículo Energizado', '{"elemento": "Energia", "categoria": "II", "espacos": 1}'::jsonb, 'Não precisa de combustível; o motorista pode atravessar um obstáculo com Pilotagem DT 25.', 'Livro de Regras, p. 151'),
('item_amaldicoado', 'Jaqueta de Veríssimo', '{"elemento": "Medo", "categoria": "IV", "espacos": 1}'::jsonb, 'Resistência a dano paranormal 15; reação e 2 PE para receber o dano no lugar de um aliado. Item único.', 'Livro de Regras, p. 151'),
('item_amaldicoado', 'Dedo Decepado', '{"elemento": "Varia", "categoria": "II", "espacos": 1}'::jsonb, 'Concede um poder paranormal do antigo dono; pode atrapalhar o descanso e chocar quem vê.', 'Livro de Regras, p. 151'),
('item_amaldicoado', 'Selos Paranormais', '{"elemento": "Varia", "espacos": 1}'::jsonb, 'Cada selo guarda um ritual que se conjura ao ler em voz alta; categoria igual ao círculo.', 'Livro de Regras, p. 151'),
('origem', 'Acadêmico', '{"pericias": "Ciências e Investigação", "subtipo": "Poder: Saber é Poder"}'::jsonb, '2 PE: +5 em um teste de Intelecto.', 'Livro de Regras, p. 16'),
('origem', 'Agente de Saúde', '{"pericias": "Intuição e Medicina", "subtipo": "Poder: Técnica Medicinal"}'::jsonb, 'Soma seu Intelecto aos PV que você cura.', 'Livro de Regras, p. 16'),
('origem', 'Amnésico', '{"pericias": "Duas à escolha do mestre", "subtipo": "Poder: Vislumbres do Passado"}'::jsonb, 'Uma vez por sessão, Intelecto DT 10 para reconhecer algo do passado: 1d4 PE temporários e talvez uma pista.', 'Livro de Regras, p. 16'),
('origem', 'Artista', '{"pericias": "Artes e Enganação", "subtipo": "Poder: Magnum Opus"}'::jsonb, 'Uma vez por missão, alguém o reconhece: +5 em testes de Presença contra essa pessoa.', 'Livro de Regras, p. 17'),
('origem', 'Atleta', '{"pericias": "Acrobacia e Atletismo", "subtipo": "Poder: 110%"}'::jsonb, '2 PE: +5 em um teste de Força ou Agilidade (exceto Luta e Pontaria).', 'Livro de Regras, p. 17'),
('origem', 'Chef', '{"pericias": "Fortitude e Profissão (cozinheiro)", "subtipo": "Poder: Ingrediente Secreto"}'::jsonb, 'No interlúdio, quem comer seu prato recebe o benefício de dois pratos.', 'Livro de Regras, p. 17'),
