('habilidade_trilha', 'Disparo Impactante', '{"classe": "Especialista", "trilha": "Atirador de Elite", "nex": 65}'::jsonb, 'Com calibre grosso, 2 PE para derrubar, desarmar, empurrar ou quebrar à distância.', 'Livro de Regras, p. 30'),
('habilidade_trilha', 'Atirar para Matar', '{"classe": "Especialista", "trilha": "Atirador de Elite", "nex": 99}'::jsonb, 'Crítico com arma de fogo causa dano máximo.', 'Livro de Regras, p. 30'),
('habilidade_trilha', 'Ataque Furtivo', '{"classe": "Especialista", "trilha": "Infiltrador", "nex": 10}'::jsonb, 'Uma vez por rodada, 1 PE: +1d6 contra alvo desprevenido ou flanqueado (+2d6 em NEX 40%, +3d6 em 65%, +4d6 em 99%).', 'Livro de Regras, p. 31'),
('habilidade_trilha', 'Gatuno', '{"classe": "Especialista", "trilha": "Infiltrador", "nex": 40}'::jsonb, '+5 em Atletismo e Crime e anda normalmente escondido.', 'Livro de Regras, p. 31'),
('habilidade_trilha', 'Assassinar', '{"classe": "Especialista", "trilha": "Infiltrador", "nex": 65}'::jsonb, 'Movimento e 3 PE: o próximo Ataque Furtivo dobra os dados extras e pode derrubar o alvo (Fortitude evita).', 'Livro de Regras, p. 31'),
